+	// Simulate a 10ms latency network, then attempt to simulate a 5ms latency
+	// network and expect an error.
+	slowConn, err := (&Network{Kbps: 0, Latency: 10 * time.Millisecond, MTU: 5}).Conn(bufConn{&bytes.Buffer{}})
+	if err != nil {
